INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d47f5523-49f3-5e17-93ae-e72d6badbeae', '99346f4a-7e98-5b7a-995a-0115caf5a5c3', '{"en": "What share of savings is given as zakat each lunar year?", "bn": "প্রতি চান্দ্র বছরে সঞ্চয়ের কত অংশ যাকাত দিতে হয়?"}', '{"en": "One fortieth (2.5%) of money and trade goods above the nisab.", "bn": "নিসাবের ওপরে থাকা টাকা ও ব্যবসায়িক পণ্যের চল্লিশ ভাগের এক ভাগ (২.৫%)।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
