INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fc4accff-5633-5644-9aaa-948fb366814e', '98c27ee6-afa5-59a2-a8da-e838aa9010f1', '{"en": "Where did the first revelation come to him?", "bn": "প্রথম ওহি কোথায় এসেছিল?"}', '{"en": "He ﷺ used to worship in the cave of Hira, where Jibril came to him.", "bn": "তিনি ﷺ হেরা গুহায় ইবাদত করতেন; সেখানেই জিবরাইল আসেন।"}', 'Sahih al-Bukhari 3', 5) ON CONFLICT (id) DO NOTHING;
