INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('439149fa-e4b4-5bb4-b30c-8240d5a15d73', '98c27ee6-afa5-59a2-a8da-e838aa9010f1', '{"en": "Who was with him in the cave during the Hijrah?", "bn": "হিজরতের সময় গুহায় তাঁর সাথে কে ছিলেন?"}', '{"en": "\"…the second of two, when they were in the cave…\"", "bn": "\"…দুজনের দ্বিতীয়জন, যখন তারা গুহায় ছিলেন…\""}', 'Quran 9:40', 7) ON CONFLICT (id) DO NOTHING;
