INSERT INTO is_challenges (id, title, description, quiz_ids, starts_at, ends_at) VALUES ('9f2e35de-3cf3-55d4-a7a5-cc3d1fd8cec5', '{"en": "Islamic Studio launch challenge", "bn": "ইসলামিক স্টুডিও উদ্বোধনী চ্যালেঞ্জ"}', '{"en": "Play all six quizzes; your best score on each counts.", "bn": "ছয়টি কুইজই খেলুন; প্রতিটিতে আপনার সেরা স্কোর গণনা হবে।"}', ARRAY['e951c998-3cf2-5a13-aef6-159c769ea83b'::uuid, 'fc7140da-27f4-51c9-945f-55e8f710a084'::uuid, '99346f4a-7e98-5b7a-995a-0115caf5a5c3'::uuid, '98c27ee6-afa5-59a2-a8da-e838aa9010f1'::uuid, 'a206e6d0-bb61-5bb9-b22d-b98cc6459466'::uuid, '9c7ce477-a546-5523-97dc-70f5e62602df'::uuid], now(), now() + interval '30 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_zakat_settings (id, rate_percent, gold_nisab_grams, silver_nisab_grams, default_nisab_basis, guidance, review_status) VALUES (true, 2.5, 87.48, 612.36, 'silver', '{"en": "Zakat is 2.5% of zakatable wealth that has stayed at or above the nisab for one full lunar year.\n\nCounts: cash, bank balances, gold and silver, goods held for sale (at today’s selling value), money owed to you that you expect to receive, and shares or investments held for trade.\nDoes not count: your home, car, furniture, clothes and tools you use for work.\nDeduct debts that are due now.\n\nScholars differ on gold and silver jewellery worn regularly (the Hanafi school counts it), and on whether to use the gold or the silver nisab; the silver nisab is lower and so benefits more of the poor. When unsure, ask a scholar you trust.", "bn": "যাকাতযোগ্য সম্পদ পূর্ণ এক চান্দ্র বছর নিসাব বা তার বেশি থাকলে তার ২.৫% যাকাত দিতে হয়।\n\nযা হিসাবে আসবে: নগদ টাকা, ব্যাংকে জমা, স্বর্ণ ও রুপা, বিক্রির জন্য রাখা পণ্য (আজকের বিক্রয়মূল্যে), পাওনা টাকা যা পাওয়ার আশা আছে, এবং ব্যবসার উদ্দেশ্যে রাখা শেয়ার বা বিনিয়োগ।\nযা আসবে না: বসবাসের বাড়ি, গাড়ি, আসবাব, পোশাক ও কাজের যন্ত্রপাতি।\nএখনই পরিশোধযোগ্য ঋণ বাদ দিন।\n\nনিয়মিত পরিধেয় স্বর্ণ-রুপার গয়না (হানাফি মাজহাবে তা হিসাবে আসে) এবং স্বর্ণ না রুপার নিসাব ধরা হবে, তা নিয়ে আলেমদের মতভেদ আছে; রুপার নিসাব কম, তাই এতে বেশি গরিব উপকৃত হয়। সন্দেহ হলে আস্থাভাজন আলেমের পরামর্শ নিন।"}', 'in_review') ON CONFLICT (id) DO NOTHING;
